+type UnknownRecord = Record<string, unknown>;
+
+export interface OpenAiCompatSnapshot<T> {
+	data: T | null;
+	approvalCapability: string | null;
+}
+
+function isStructuredObject(value: unknown): value is UnknownRecord {
+	return Boolean(value) && typeof value === "object" && !Array.isArray(value);
+}
+
+export function approvalCapabilityFromMeta(meta: unknown): string | null {
+	if (!isStructuredObject(meta)) return null;
+	const token = meta["lobu/approval-capability"];
+	return typeof token === "string" && token.length <= 4_096 ? token : null;
+}
+
+function approvalCapabilityFromResult(result: unknown): string | null {
+	if (!isStructuredObject(result)) return null;
+	return approvalCapabilityFromMeta(result._meta);
+}
+
+/**
+ * Read ChatGPT's compatibility globals without making them a dependency of the
+ * portable MCP Apps bridge. ChatGPT restores these globals for historical
+ * cards, including after the standard tool-result notification has already
+ * happened in an earlier page lifetime.
+ */
+export function readOpenAiCompatSnapshot<T>(
+	globals: unknown,
+): OpenAiCompatSnapshot<T> {
+	if (!isStructuredObject(globals)) {
+		return { data: null, approvalCapability: null };
+	}
+
+	const data = isStructuredObject(globals.toolOutput)
+		? (globals.toolOutput as T)
+		: null;
+	const metadata = isStructuredObject(globals.toolResponseMetadata)
+		? globals.toolResponseMetadata
+		: null;
+	const approvalCapability = metadata
+		? (approvalCapabilityFromResult(metadata.mcp_tool_result) ??
+			approvalCapabilityFromResult(metadata.call_tool_result))
+		: null;
+
+	return { data, approvalCapability };
+}

